            if (!placed) {
                for (let i = 0; i < totalTables; i++) {
                    if (tables[i].length < targetSize) {
                        tables[i].push(guest);
                        break;
                    }
                }
            }
        });

        renderTables(tables);
    }

    function renderTables(tables) {
        tablesContainer.innerHTML = '';
        tables.forEach((table, index) => {
            const card = document.createElement('div');
            card.className = 'table-card';

            const diets = table.filter(g => g.diet).map(g => g.diet);
            const dietBadge = diets.length ? `<span class="tag diet" style="float:right;">${diets.length} Alert(s)</span>` : '';

            card.innerHTML = `
                <div class="table-title">
                    <span>Table ${index + 1}</span>
                    ${dietBadge}
                </div>
            `;

            table.forEach(g => {
                const item = document.createElement('div');
                item.className = 'table-guest';

                let detail = '';
                if (g.diet) detail += ` (${g.diet})`;
                if (g.tag) detail += ` [${g.tag}]`;

                item.innerHTML = `• <strong>${g.name}</strong><span style="font-size:0.8rem; color:var(--text-light)">${detail}</span>`;
                card.appendChild(item);
            });

            tablesContainer.appendChild(card);
        });
    }

    shuffleBtn.addEventListener('click', generateLayout);
    printBtn.addEventListener('click', () => window.print());

    demoBtn.addEventListener('click', () => {
        guests = JSON.parse(JSON.stringify(demoGuests));
        updateStorage();
        generateLayout();
    });

    clearBtn.addEventListener('click', () => {
        guests = [];
        updateStorage();
        tablesContainer.innerHTML = '<p style="color: var(--text-light); grid-column: 1/-1;">Add guests and click "Mix Seating" to generate tables.</p>';
    });

    renderGuests();
</script>
</body>
</html>
